package com.mittiandmore.dto;
import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDateTime;
public class DiscountRequest {
 @NotBlank @Size(max=40) private String code; @NotBlank private String type; @NotNull @DecimalMin("0.00") private BigDecimal value; @NotNull @DecimalMin("0.00") private BigDecimal minimumOrderValue=BigDecimal.ZERO; @DecimalMin("0.00") private BigDecimal maxDiscount; private LocalDateTime startsAt,expiresAt; @Min(1) private Integer usageLimit; private Boolean active=true; private Boolean firstTimeOnly=false;
 public Boolean getFirstTimeOnly(){return firstTimeOnly;} public void setFirstTimeOnly(Boolean v){firstTimeOnly=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getType(){return type;} public void setType(String v){type=v;} public BigDecimal getValue(){return value;} public void setValue(BigDecimal v){value=v;} public BigDecimal getMinimumOrderValue(){return minimumOrderValue;} public void setMinimumOrderValue(BigDecimal v){minimumOrderValue=v;} public BigDecimal getMaxDiscount(){return maxDiscount;} public void setMaxDiscount(BigDecimal v){maxDiscount=v;} public LocalDateTime getStartsAt(){return startsAt;} public void setStartsAt(LocalDateTime v){startsAt=v;} public LocalDateTime getExpiresAt(){return expiresAt;} public void setExpiresAt(LocalDateTime v){expiresAt=v;} public Integer getUsageLimit(){return usageLimit;} public void setUsageLimit(Integer v){usageLimit=v;} public Boolean getActive(){return active;} public void setActive(Boolean v){active=v;}
}
